<template><div class="wrap"><div class="page-head"><h1>Top tipsters</h1><p class="muted">Compare transparent performance before following a tipster.</p></div><div class="grid3"><RouterLink v-for="t in items" :key="t._id" :to="`/tipsters/${t.username}`" class="card"><div class="tipster"><div class="tipster-avatar">{{t.username?.[0]?.toUpperCase()}}</div><div><h3>@{{t.username}}</h3><div class="muted small">{{t.country||'Football tipster'}}</div></div></div><p class="muted small" style="line-height:1.6">{{t.bio}}</p><div class="kpis"><div class="stat"><span class="muted small">Win rate</span><b>{{rate(t)}}%</b></div><div class="stat"><span class="muted small">Streak</span><b>{{t.currentStreak||0}}</b></div></div><div style="margin-top:15px"><div class="bar"><span :style="{width:`${Math.min(rate(t),100)}%`}"/></div></div></RouterLink></div><div v-if="!items.length" class="empty">No approved tipsters yet.</div></div></template>
<script setup lang="ts">import {onMounted,ref} from 'vue';import {RouterLink} from 'vue-router';import {api} from '../services/api';const items=ref<any[]>([]);const rate=(t:any)=>t.totalTips?Math.round((t.wins/t.totalTips)*1000)/10:0;onMounted(async()=>{try{items.value=(await api.get('/tipsters')).data}catch{}})</script>
